from collections import deque

def match_parens(lst):
    s1, s2 = lst
    if (s1[0] == ')' and s2[-1] == '(') or (s2[0] == ')' and s1[-1] == '('):
        return 'No'
    else:
        if s1[0] == '(':
            stack = deque(s1[1:])
            for c in s2:
                if c == '(':
                    stack.append(c)
                else:
                    if not stack:
                        return 'No'
                    stack.pop()
        else:
            stack = deque(s2[1:])
            for c in s1:
                if c == '(':
                    stack.append(c)
                else:
                    if not stack:
                        return 'No'
                    stack.pop()
        return 'Yes' if not stack else 'No'
```

