def get_odd_collatz(n):
    # Start with the given number
    sequence = [n]

    # Apply the Collatz rule until the sequence reaches 1
    while sequence[-1] != 1:
        if sequence[-1] % 2 == 0:
            sequence.append(sequence[-1] // 2)
        else:
            sequence.append(sequence[-1] * 3 + 1)

    # Filter out the even numbers and sort the remaining odd numbers
    return sorted([num for num in sequence if num % 2 != 0])
```

